class Badge:
    def __init__(self, name, score):
        self.name = name
        self.score = score

    def __repr__(self):
        return f"Badge({self.name!r}, {self.score!r})"

    def __str__(self):
        return f"{self.name} ({self.score})"

def inspect_badge(obj):
    return getattr(obj, "name", "anonymous"), hasattr(obj, "score"), "name" in dir(obj)

print(repr(Badge("Ada", 3)))
